36. Collect comments with a status log

## =============================================================================
## Collect comments with a status log
## =============================================================================

collect_comments &lt;- function(video_id, n_max = 300) {

  status &lt;- "ok"
  started_at &lt;- format(Sys.time(), tz = "UTC", usetz = TRUE)
  quota_before &lt;- yt_get_quota_usage()

  out &lt;- tryCatch(
    withCallingHandlers(
      get_all_comments(video_id, max_results = n_max),

      tuber_comments_disabled = function(w) {
        status &lt;&lt;- "disabled"
        invokeRestart("muffleWarning")
      },

      tuber_no_comments = function(w) {
        if (status == "ok") status &lt;&lt;- "none"
        invokeRestart("muffleWarning")
      }
    ),
    error = function(e) e
  )

  quota_after &lt;- yt_get_quota_usage()

  units_used &lt;- sum(
    quota_after$quota_used[quota_after$bucket == "data"]
  ) - sum(
    quota_before$quota_used[quota_before$bucket == "data"]
  )

  finished_at &lt;- format(Sys.time(), tz = "UTC", usetz = TRUE)
  Sys.sleep(1)

  if (inherits(out, "error")) {

    error_message &lt;- conditionMessage(out)

    ## Ensure the key cannot enter a saved error message
    key &lt;- Sys.getenv("YOUTUBE_KEY")
    if (nzchar(key)) {
      error_message &lt;- gsub(
        key, "&lt;REDACTED&gt;", error_message, fixed = TRUE
      )
    }

    return(list(
      data = NULL,
      log = tibble(
        video_id,
        status = "error",
        n_returned = 0L,
        n_unique = 0L,
        duplicates_removed = 0L,
        data_units = units_used,
        started_at,
        finished_at,
        message = error_message
      )
    ))
  }

  out &lt;- as_tibble(out)
  n_returned &lt;- nrow(out)

  if (n_returned &gt; 0L) {
    out &lt;- out |&gt;
      distinct(comment_id, .keep_all = TRUE)

    stopifnot(nrow(out) &lt;= n_max)
  } else if (status == "ok") {
    status &lt;- "none"
  }

  list(
    data = out,
    log = tibble(
      video_id,
      status,
      n_returned,
      n_unique = nrow(out),
      duplicates_removed = n_returned - nrow(out),
      data_units = units_used,
      started_at,
      finished_at,
      message = NA_character_
    )
  )
}

