77. Repair video metadata using saved collection-run provenance

## =============================================================================
## Repair video metadata using saved collection-run provenance
## =============================================================================

repair_comments &lt;- function(runs_path, video_info_path, period_label) {

  runs &lt;- read_rds(runs_path)
  video_info &lt;- read_rds(video_info_path)

  video_lookup &lt;- video_info |&gt;
    select(
      video_id,
      channel_title,
      video_title = title,
      video_date = date
    ) |&gt;
    distinct()

  stopifnot(!anyDuplicated(video_lookup$video_id))

  repaired &lt;- map_dfr(runs, function(run) {

    if (is.null(run$data) || nrow(run$data) == 0L) {
      return(tibble())
    }

    requested_id &lt;- unique(run$log$video_id)

    stopifnot(
      length(requested_id) == 1L,
      !is.na(requested_id),
      nzchar(requested_id)
    )

    x &lt;- as_tibble(run$data)

    if (!"video_id" %in% names(x)) {
      x$video_id &lt;- NA_character_
    }

    existing_id &lt;- as.character(x$video_id)
    missing_id &lt;- is.na(existing_id) | trimws(existing_id) == ""

    ## Stop if a populated ID contradicts the recorded request
    stopifnot(all(existing_id[!missing_id] == requested_id))

    x$video_id &lt;- existing_id
    x$video_id[missing_id] &lt;- requested_id

    x
  }) |&gt;
    distinct(comment_id, .keep_all = TRUE) |&gt;
    select(-any_of(c(
      "channel_title", "video_title", "video_date", "video_period"
    ))) |&gt;
    left_join(
      video_lookup,
      by = "video_id",
      relationship = "many-to-one"
    ) |&gt;
    mutate(video_period = period_label)

  stopifnot(
    !anyDuplicated(repaired$comment_id),
    !anyNA(repaired$video_id),
    !anyNA(repaired$channel_title),
    !anyNA(repaired$video_date),
    !anyNA(repaired$video_period)
  )

  repaired
}

